      bp: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    };
  };

  const summary = { closed: summarize(closed), open: summarize(open) };
  console.log(JSON.stringify(summary, null, 2));

  if (summary.closed.wcag.length || summary.open.wcag.length) {
    process.exitCode = 1;
  }
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
